parameters.jsCode:
const raw = $json.output?.[0]?.content?.[0]?.text ?? $json.text ?? "";
const norm = $('Normalize Info').item.json;
let ai = {};
let aiError = false;
try { ai = JSON.parse(String(raw).replace(/```json/gi, "").replace(/```/g, "").trim()); } catch (e) { aiError = true; }
const WEIGHTS = { urgency: { High: 40, Medium: 20, Low: 10 }, timeline: { "Immediately": 30, "Within 1 Month": 20, "Within 3 Months": 10, "6+ Months": 5 }, budget: 20, contact: 10 };
let score = 0;
score += WEIGHTS.urgency[ai.urgency] || 0;
score += WEIGHTS.timeline[ai.timeline] || 0;
if (ai.budgetSuitable === true) score += WEIGHTS.budget;
if (norm.lead?.email && norm.lead?.phone) score += WEIGHTS.contact;
const emotion = String(ai.emotion || "").toLowerCase();
const sentiment = String(ai.sentiment || "").toLowerCase();
if (/(urgent|critical|anxious|desperate)/.test(emotion)) score += 10;
if (sentiment.includes("negative") && ai.urgency === "High") score += 5;
if (score > 100) score = 100;
const email = String(norm.lead?.email || "").toLowerCase();
const phoneDigits = String(norm.lead?.phone || "").replace(/\D/g, "");
const msg = String(norm.message || "");
const disposable = ["mailinator.com","tempmail.com","10minutemail.com","guerrillamail.com","yopmail.com","trashmail.com","sharklasers.com","getnada.com","dispostable.com"];
const emailDomain = email.split("@")[1] || "";
let spamScore = Number(ai.spamScore) || 0;
const reasons = Array.isArray(ai.spamReasons) ? [...ai.spamReasons] : [];
if (disposable.includes(emailDomain)) { spamScore = Math.max(spamScore, 90); reasons.push("Disposable email domain"); }
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) { spamScore = Math.max(spamScore, 80); reasons.push("Invalid email format"); }
if (phoneDigits.length < 7 || phoneDigits.length > 15) { spamScore = Math.max(spamScore, 70); reasons.push("Suspicious phone number"); }
if (msg && /(.)\1{6,}/.test(msg)) { spamScore = Math.max(spamScore, 75); reasons.push("Gibberish / repeated characters"); }
if (spamScore > 100) spamScore = 100;
const isSpam = spamScore >= 70;
let category = "Cold";
if (score >= 80) category = "Hot"; else if (score >= 50) category = "Warm";
let priority = "P3";
if (category === "Hot") priority = "P1"; else if (category === "Warm") priority = "P2";
if (aiError) { category = "Review Required"; priority = "Manual Review"; score = 0; }
return { ...norm, ai, language: ai.language || "English", translatedMessage: ai.translatedMessage || norm.message, sentiment: ai.sentiment || "", emotion: ai.emotion || "", spamScore, spamReasons: reasons, isSpam, rawAIResponse: raw, aiError, leadScore: score, leadCategory: category, priority };

