// Next business day at 14:00 Africa/Lagos (UTC+1 => 13:00 UTC)
const now = new Date();
let d = new Date(now.getTime() + 24*60*60*1000);
d.setUTCHours(13,0,0,0);
// skip weekend (Sat=6, Sun=0) in Lagos which matches UTC day here
let day = d.getUTCDay();
while (day === 6 || day === 0) { d = new Date(d.getTime() + 24*60*60*1000); d.setUTCHours(13,0,0,0); day = d.getUTCDay(); }
const startISO = d.toISOString();
const endISO = new Date(d.getTime() + 60*60*1000).toISOString();
let human;
try { human = d.toLocaleString('en-GB', { timeZone: 'Africa/Lagos', weekday:'long', year:'numeric', month:'long', day:'numeric', hour:'2-digit', minute:'2-digit' }); } catch (e) { human = startISO; }
return { bookingStartISO: startISO, bookingEndISO: endISO, bookingHuman: human };

